import KnoopByKnoopCore
import MapLibre
import SwiftUI

/// OpenStreetMap-based base maps without API key, see the design of `add-planning-screens`, light or
/// dark, see `map-planning` "Light and dark appearance": OpenFreeMap's liberty, or its dark variant
/// shipped with the app, generated by `:pipeline:darkStyle`.
private func baseMapStyle(dark: Bool) -> URL {
  if dark, let shipped = Bundle.main.url(forResource: "liberty-dark", withExtension: "json") {
    return shipped
  }
  return URL(string: "https://tiles.openfreemap.org/styles/liberty")!
}

/// Used when the base map cannot be loaded, e.g. offline on first start: the network layers still
/// show. Offline, MapLibre takes long to fail, so it is used after a timeout.
private func offlineStyle(dark: Bool) -> String {
  """
  {"version": 8, "sources": {}, "layers": [{"id": "background", "type": "background", \
  "paint": {"background-color": "\(dark ? "#1E2320" : "#EEF1EA")"}}]}
  """
}

/// How long the base map may take to load before the offline style is used.
private let baseMapTimeout: TimeInterval = 3

/// How long after falling back to the offline style the base map is loaded again, see
/// `map-planning` "Slow base map": setting the offline style cancelled its loading. MapLibre shows the
/// offline style until the base map has loaded.
private let baseMapRetry: TimeInterval = 2

/// The zoom level a search hit is shown at: streets and knots around it are easy to tap.
private let searchHitZoom = 14.0

/// The zoom when navigation begins: close enough to see the next knot and the way to it.
private let navigationZoom = 15.0
private let routeWidth: CGFloat = 5
private let routeWidthCalm: CGFloat = 3
private let routeWidthAhead: CGFloat = 7
private let trackWidth: CGFloat = 3
private let routeOffset: CGFloat = 4

/// How opaque the copies of the base map's bridges over the route are, see `map-planning` "Route
/// and bridges".
private let bridgeOpacity = 0.6
private let bridgeCopySuffix = "-over"
/// Our line layers and their copies drawn on top of the bridges for the stretches on a bridge.
private let bridgeLines = [
  ("connections", "connections-bridge"), ("route", "route-bridge"), ("route-ahead", "route-ahead-bridge"),
]
/// The edges of a bridge along the route where it runs on one, see "Bridge edges on the route".
private let bridgeEdgesSuffix = "-bridge-edges"
private let bridgeEdgeOpacity = 0.45
private let bridgeEdgeWidth: CGFloat = 1.5

/// Whether a layer of the base map is one of its bridges, road, path or railway, with outlines.
func isBaseMapBridge(_ identifier: String) -> Bool { identifier.hasPrefix("bridge_") }

/// Knots are drawn and can be tapped from this zoom level on.
private let knotMinimumZoom = 10.0
/// How close the position button goes.
private let myPositionZoom = 14.0

/// The touch target around a tap within which the nearest knot is picked.
private let touchTargetPoints = 24.0

/// A place on the map, saved when the app goes to the background, see `faster-startup`.
struct CameraPlace: Codable {
  let latitude: Double
  let longitude: Double
  let zoom: Double
}

/// The map with the network and the route. Taps are reported with the touch target in meters at
/// the current zoom level, so the core's knot locator can pick the knot.
///
/// The map is shown before a network is loaded (`graph` and `layers` `nil`), at `initialPlace` if
/// there is one, see `map-planning` "Map, knots and courses one after the other".
struct NetworkMapView: UIViewRepresentable {

  let graph: NetworkGraph?
  let layers: MapLayers?
  /// The knots to show when a network is opened, e.g. those of a restored route.
  let focus: [Knot]
  /// A tap with its position, the touch target in meters, and where on the map it was.
  let onTap: (Double, Double, Double, CGPoint) -> Void
  /// Whether the device has internet access; the base map is loaded again once it is back.
  let online: Bool
  /// Where the map opens: where it was when the app was left last.
  let initialPlace: CameraPlace?
  /// Called with the map's place when the app goes to the background.
  let onLeave: (CameraPlace) -> Void
  /// The chosen search hit, shown with a marker; the map moves there, see `place-search`.
  let marker: PlaceHit?
  /// Called with the map's place whenever it stopped moving.
  let onMove: (CameraPlace, GeoBounds?) -> Void
  /// The rider's position while navigating, see `knot-navigation` "Position on the map".
  var position: Fix? = nil
  /// The next knot while navigating, highlighted.
  var nextKnot: Knot? = nil
  /// Whether navigation has begun, so the route is calm, see `knot-navigation` "Leg ahead on the
  /// map".
  var navigating = false
  /// The course to the next knot, see `knot-navigation` "Leg ahead on the map".
  var courseAhead: [GeoPoint]? = nil
  /// Off route, where the line back to the route ends, see `knot-navigation` "Way to the route on
  /// the map"; `nil` on the route.
  var wayToRoute: GeoPoint? = nil
  /// Off route, the way along paths, see `knot-navigation` "Guided way back to the route".
  var guidedWay: [GeoPoint]? = nil
  /// The track ridden while navigating, see `knot-navigation` "Ridden track".
  var track: RiddenTrack? = nil
  /// The riding direction, see `knot-navigation` "Riding direction on the map".
  var direction: Double? = nil
  /// The position found on request while planning, see `map-planning` "Show my position".
  var myPosition: Fix? = nil
  /// Whether the position is being found.
  var locating = false
  /// Asks for the position; `nil` while navigating, which hides the button.
  var onLocate: (() -> Void)? = nil
  /// Whether the nearest knots are being found.
  var findingNearest = false
  /// Shows the nearest knots; `nil` while knots are in view, which hides the button.
  var onShowNearest: (() -> Void)? = nil
  /// Where the map moved for the nearest knots last.
  var nearestKnots: NearestKnots? = nil
  /// A coming knot to show while navigating, see `knot-navigation` "Showing a coming knot on the
  /// map".
  var shownKnot: ShownKnot? = nil
  /// A tapped place offered as a route point, marked with a flag on the map, see `map-planning`
  /// "Choose a route point on the map".
  var offerPlace: GeoPoint? = nil
  /// Called with where `offerPlace` is on the screen while the map moves, so its choices follow.
  var onOfferMoved: (CGPoint) -> Void = { _ in }

  func makeCoordinator() -> Coordinator { Coordinator() }

  func makeUIView(context: Context) -> MLNMapView {
    let coordinator = context.coordinator
    coordinator.dark = context.environment.colorScheme == .dark
    coordinator.online = online
    // Offline, MapLibre would wait for the base map, and nothing can be drawn without a style.
    let mapView = MLNMapView(frame: .zero, styleURL: nil)
    // Set explicitly, as MapLibre otherwise falls back on the deprecated
    // `UIViewController.automaticallyAdjustsScrollViewInsets` and warns at startup; `true` is what
    // that fallback did.
    mapView.automaticallyAdjustsContentInset = true
    // The planner sheet is presented over the map; without this, UIKit dims the tint of the map's
    // buttons behind it, so the recenter icon turned pale green and the zoom icons gray.
    mapView.tintAdjustmentMode = .normal
    mapView.delegate = coordinator
    if online { coordinator.loadBaseMap(on: mapView) } else { coordinator.useOfflineStyle(on: mapView) }
    if let initialPlace {
      mapView.setCenter(
        CLLocationCoordinate2D(latitude: initialPlace.latitude, longitude: initialPlace.longitude),
        zoomLevel: initialPlace.zoom, animated: false)
      context.coordinator.hasPlace = true
    }
    context.coordinator.observeLeaving(of: mapView)
    mapView.compassView.isHidden = true
    let tap = UITapGestureRecognizer(target: context.coordinator, action: #selector(Coordinator.tapped(_:)))
    // Double taps zoom the map and must not select knots.
    for recognizer in mapView.gestureRecognizers ?? [] {
      if let other = recognizer as? UITapGestureRecognizer, other.numberOfTapsRequired == 2 {
        tap.require(toFail: other)
      }
    }
    mapView.addGestureRecognizer(tap)
    addZoomButtons(to: mapView, coordinator: context.coordinator)
    if online {
      DispatchQueue.main.asyncAfter(deadline: .now() + baseMapTimeout) { [weak mapView] in
        guard let mapView, coordinator.style == nil else { return }
        coordinator.useOfflineStyle(on: mapView)
        DispatchQueue.main.asyncAfter(deadline: .now() + baseMapRetry) { [weak mapView] in
          if let mapView, coordinator.usesOfflineStyle, coordinator.online { coordinator.loadBaseMap(on: mapView) }
        }
      }
    }
    return mapView
  }

  /// Buttons to zoom in and out, in addition to the gestures.
  private func addZoomButtons(to mapView: MLNMapView, coordinator: Coordinator) {
    let buttons = [("plus", #selector(Coordinator.zoomIn)), ("minus", #selector(Coordinator.zoomOut))].map {
      symbol, action in
      let button = UIButton(type: .system)
      button.setImage(UIImage(systemName: symbol), for: .normal)
      button.tintColor = UIColor(Color.knoopGreen)
      button.backgroundColor = UIColor { $0.userInterfaceStyle == .dark ? UIColor(white: 0.17, alpha: 1) : .white }
      button.layer.cornerRadius = 20
      button.layer.shadowOpacity = 0.2
      button.layer.shadowRadius = 2
      button.layer.shadowOffset = CGSize(width: 0, height: 1)
      button.widthAnchor.constraint(equalToConstant: 40).isActive = true
      button.heightAnchor.constraint(equalToConstant: 40).isActive = true
      button.addTarget(coordinator, action: action, for: .touchUpInside)
      return button
    }
    let stack = UIStackView(arrangedSubviews: buttons)
    stack.axis = .vertical
    stack.spacing = 8
    stack.translatesAutoresizingMaskIntoConstraints = false
    mapView.addSubview(stack)
    // Only while navigating and after the user moved the map away from the rider, below the zoom
    // buttons, so they don't move when it appears, see `knot-navigation` "Following the rider".
    let recenter = UIButton(type: .system)
    recenter.setImage(UIImage(systemName: "location.fill"), for: .normal)
    recenter.tintColor = .white
    recenter.backgroundColor = UIColor(Color.actionGreen)
    recenter.layer.cornerRadius = 20
    recenter.layer.shadowOpacity = 0.2
    recenter.layer.shadowRadius = 2
    recenter.layer.shadowOffset = CGSize(width: 0, height: 1)
    recenter.accessibilityLabel = String(localized: "Recenter", bundle: AppLanguage.bundle)
    recenter.isHidden = true
    recenter.translatesAutoresizingMaskIntoConstraints = false
    recenter.addTarget(coordinator, action: #selector(Coordinator.recenter), for: .touchUpInside)
    mapView.addSubview(recenter)
    coordinator.recenterButton = recenter
    // While planning, in the recenter button's place: the position once per tap, see `map-planning`
    // "Show my position".
    let locate = UIButton(type: .system)
    locate.setImage(UIImage(systemName: "location"), for: .normal)
    locate.tintColor = UIColor(Color.knoopGreen)
    locate.backgroundColor = UIColor { $0.userInterfaceStyle == .dark ? UIColor(white: 0.17, alpha: 1) : .white }
    locate.layer.cornerRadius = 20
    locate.layer.shadowOpacity = 0.2
    locate.layer.shadowRadius = 2
    locate.layer.shadowOffset = CGSize(width: 0, height: 1)
    locate.accessibilityLabel = String(localized: "My position", bundle: AppLanguage.bundle)
    locate.translatesAutoresizingMaskIntoConstraints = false
    locate.addTarget(coordinator, action: #selector(Coordinator.locate), for: .touchUpInside)
    let spinner = UIActivityIndicatorView(style: .medium)
    spinner.translatesAutoresizingMaskIntoConstraints = false
    spinner.isUserInteractionEnabled = false
    locate.addSubview(spinner)
    mapView.addSubview(locate)
    coordinator.locateButton = locate
    coordinator.locateSpinner = spinner
    // While planning with no knots in view, see `map-planning` "Nearest knots".
    let nearest = UIButton(type: .system)
    nearest.setImage(UIImage(systemName: "signpost.right"), for: .normal)
    nearest.tintColor = UIColor(Color.knoopGreen)
    nearest.backgroundColor = UIColor { $0.userInterfaceStyle == .dark ? UIColor(white: 0.17, alpha: 1) : .white }
    nearest.layer.cornerRadius = 20
    nearest.layer.shadowOpacity = 0.2
    nearest.layer.shadowRadius = 2
    nearest.layer.shadowOffset = CGSize(width: 0, height: 1)
    nearest.accessibilityLabel = String(localized: "Show the nearest knots", bundle: AppLanguage.bundle)
    nearest.isHidden = true
    nearest.translatesAutoresizingMaskIntoConstraints = false
    nearest.addTarget(coordinator, action: #selector(Coordinator.showNearest), for: .touchUpInside)
    let nearestSpinner = UIActivityIndicatorView(style: .medium)
    nearestSpinner.translatesAutoresizingMaskIntoConstraints = false
    nearestSpinner.isUserInteractionEnabled = false
    nearest.addSubview(nearestSpinner)
    mapView.addSubview(nearest)
    coordinator.nearestButton = nearest
    coordinator.nearestSpinner = nearestSpinner
    NSLayoutConstraint.activate([
      nearest.widthAnchor.constraint(equalToConstant: 40),
      nearest.heightAnchor.constraint(equalToConstant: 40),
      nearest.trailingAnchor.constraint(equalTo: stack.trailingAnchor),
      nearest.topAnchor.constraint(equalTo: locate.bottomAnchor, constant: 8),
      nearestSpinner.centerXAnchor.constraint(equalTo: nearest.centerXAnchor),
      nearestSpinner.centerYAnchor.constraint(equalTo: nearest.centerYAnchor),
      stack.trailingAnchor.constraint(equalTo: mapView.safeAreaLayoutGuide.trailingAnchor, constant: -12),
      stack.centerYAnchor.constraint(equalTo: mapView.centerYAnchor),
      recenter.widthAnchor.constraint(equalToConstant: 40),
      recenter.heightAnchor.constraint(equalToConstant: 40),
      recenter.trailingAnchor.constraint(equalTo: stack.trailingAnchor),
      recenter.topAnchor.constraint(equalTo: stack.bottomAnchor, constant: 20),
      locate.widthAnchor.constraint(equalToConstant: 40),
      locate.heightAnchor.constraint(equalToConstant: 40),
      locate.trailingAnchor.constraint(equalTo: stack.trailingAnchor),
      locate.topAnchor.constraint(equalTo: stack.bottomAnchor, constant: 20),
      spinner.centerXAnchor.constraint(equalTo: locate.centerXAnchor),
      spinner.centerYAnchor.constraint(equalTo: locate.centerYAnchor),
    ])
  }

  func updateUIView(_ mapView: MLNMapView, context: Context) {
    // Again on each update, so they follow the language chosen in the info sheet.
    context.coordinator.recenterButton?.accessibilityLabel =
      String(localized: "Recenter", bundle: AppLanguage.bundle)
    context.coordinator.locateButton?.accessibilityLabel =
      String(localized: "My position", bundle: AppLanguage.bundle)
    context.coordinator.onTap = onTap
    context.coordinator.onLeave = onLeave
    context.coordinator.onMove = onMove
    context.coordinator.showMarker(marker, on: mapView)
    context.coordinator.onOfferMoved = onOfferMoved
    context.coordinator.showOffer(offerPlace)
    context.coordinator.showNavigation(
      position: position, nextKnot: nextKnot, wayToRoute: wayToRoute, guidedWay: guidedWay, direction: direction, on: mapView)
    context.coordinator.showTrack(track)
    context.coordinator.showLegAhead(navigating: navigating, courseAhead: courseAhead, geometry: layers?.geometry)
    context.coordinator.showKnot(shownKnot, on: mapView)
    context.coordinator.onLocate = onLocate
    context.coordinator.showLocating(locating, available: onLocate != nil)
    context.coordinator.nearestButton?.accessibilityLabel =
      String(localized: "Show the nearest knots", bundle: AppLanguage.bundle)
    context.coordinator.onShowNearest = onShowNearest
    context.coordinator.showFindingNearest(findingNearest, available: onShowNearest != nil)
    context.coordinator.showMyPosition(myPosition, center: myPosition !== nearestKnots?.rider, on: mapView)
    context.coordinator.showNearestKnots(nearestKnots, on: mapView)
    context.coordinator.dark = context.environment.colorScheme == .dark
    context.coordinator.online = online
    if online && context.coordinator.usesOfflineStyle {
      context.coordinator.loadBaseMap(on: mapView)
    }
    // Switched in place, the camera stays, see `map-planning` "Switching while the app is open".
    context.coordinator.reloadStyleIfAppearanceChanged(on: mapView)
    context.coordinator.show(graph: graph, layers: layers, focus: focus, on: mapView)
  }

  /// Keeps the style and what is shown, so updates only touch what changed.
  final class Coordinator: NSObject, MLNMapViewDelegate {

    var onTap: (Double, Double, Double, CGPoint) -> Void = { _, _, _, _ in }
    var onLeave: (CameraPlace) -> Void = { _ in }
    var onMove: (CameraPlace, GeoBounds?) -> Void = { _, _ in }
    var onOfferMoved: (CGPoint) -> Void = { _ in }
    private var offerPlace: GeoPoint?
    var onLocate: (() -> Void)?
    weak var locateButton: UIButton?
    weak var locateSpinner: UIActivityIndicatorView?
    var onShowNearest: (() -> Void)?
    weak var nearestButton: UIButton?
    weak var nearestSpinner: UIActivityIndicatorView?
    private var shownNearest: NearestKnots?
    private var myPosition: Fix?
    private var marker: PlaceHit?

    @objc func locate() { onLocate?() }

    func showLocating(_ locating: Bool, available: Bool) {
      locateButton?.isHidden = !available
      locateButton?.imageView?.alpha = locating ? 0 : 1
      if locating { locateSpinner?.startAnimating() } else { locateSpinner?.stopAnimating() }
    }

    @objc func showNearest() { onShowNearest?() }

    func showFindingNearest(_ finding: Bool, available: Bool) {
      nearestButton?.isHidden = !available
      nearestButton?.imageView?.alpha = finding ? 0 : 1
      if finding { nearestSpinner?.startAnimating() } else { nearestSpinner?.stopAnimating() }
    }

    /// The rider and the nearest knot in view with the knots shown, no closer than the position
    /// button goes; the knot alone where they are too far apart, see `map-planning` "Nearest knots".
    func showNearestKnots(_ target: NearestKnots?, on mapView: MLNMapView) {
      guard let target, target !== shownNearest else { return }
      shownNearest = target
      let knot = CLLocationCoordinate2D(latitude: target.knot.latitude, longitude: target.knot.longitude)
      if let fix = target.rider, fix.latitude != knot.latitude || fix.longitude != knot.longitude {
        let bounds = MLNCoordinateBounds(
          sw: CLLocationCoordinate2D(latitude: min(fix.latitude, knot.latitude), longitude: min(fix.longitude, knot.longitude)),
          ne: CLLocationCoordinate2D(latitude: max(fix.latitude, knot.latitude), longitude: max(fix.longitude, knot.longitude)))
        let padding = clearPadding(in: mapView)
        let camera = mapView.cameraThatFitsCoordinateBounds(bounds, edgePadding: padding)
        let latitude = camera.centerCoordinate.latitude
        let farthest = MLNAltitudeForZoomLevel(knotMinimumZoom, camera.pitch, latitude, mapView.frame.size)
        if camera.altitude <= farthest {
          camera.altitude = max(
            camera.altitude, MLNAltitudeForZoomLevel(myPositionZoom, camera.pitch, latitude, mapView.frame.size))
          center(camera, on: bounds, padding: padding, in: mapView)
          mapView.setCamera(camera, animated: true)
          return
        }
      }
      mapView.setCenter(knot, zoomLevel: knotMinimumZoom, animated: true)
    }

    /// The part of the map above the panel, which the map lies below, or `nil` if it is zoomed out
    /// too far for knots to show.
    private func knotArea(of mapView: MLNMapView) -> GeoBounds? {
      guard mapView.zoomLevel >= knotMinimumZoom else { return nil }
      var visible = mapView.bounds
      visible.size.height = max(0, visible.height - edgePadding(in: mapView).bottom)
      let bounds = mapView.convert(visible, toCoordinateBoundsFrom: mapView)
      return GeoBounds(
        minLatitude: bounds.sw.latitude, minLongitude: bounds.sw.longitude,
        maxLatitude: bounds.ne.latitude, maxLongitude: bounds.ne.longitude)
    }

    /// Marks `newPosition`, found on request, and centers the map on it with the knots shown, unless
    /// the map is moved otherwise.
    func showMyPosition(_ newPosition: Fix?, center: Bool, on mapView: MLNMapView) {
      guard newPosition !== myPosition else { return }
      myPosition = newPosition
      updateMyPosition()
      guard let newPosition, center else { return }
      mapView.setCenter(
        CLLocationCoordinate2D(latitude: newPosition.latitude, longitude: newPosition.longitude),
        zoomLevel: max(mapView.zoomLevel, myPositionZoom), animated: true)
    }

    private func updateMyPosition() {
      let point = myPosition.map { fix -> MLNPointFeature in
        let feature = MLNPointFeature()
        feature.coordinate = CLLocationCoordinate2D(latitude: fix.latitude, longitude: fix.longitude)
        return feature
      }
      (style?.source(withIdentifier: "my-position") as? MLNShapeSource)?.shape = point
    }

    func showMarker(_ newMarker: PlaceHit?, on mapView: MLNMapView) {
      guard newMarker != marker else { return }
      marker = newMarker
      updateMarker()
      if let newMarker {
        mapView.setCenter(
          CLLocationCoordinate2D(latitude: newMarker.latitude, longitude: newMarker.longitude),
          zoomLevel: searchHitZoom, animated: true)
      }
    }

    private var position: Fix?
    private var nextKnot: Knot?
    private var wayToRoute: GeoPoint?
    private var guidedWay: [GeoPoint]?

    /// Whether the map moves to the rider with the next position, e.g. after the app was opened.
    var findRider = false

    private var direction: Double?
    private var track: RiddenTrack?
    weak var recenterButton: UIButton?

    /// Whether the map follows the rider while navigating, see `knot-navigation` "Following the
    /// rider": from the start of navigation until the user moves the map, and again after
    /// `recenter`.
    private var following = false {
      didSet { updateRecenterButton() }
    }

    private func updateRecenterButton() {
      recenterButton?.isHidden = position == nil || following
    }

    /// The request of the knot shown last, so each tap shows it once.
    private var shownRequest = 0

    /// Shows the knot at the navigation zoom and stops following the rider, as a move by hand.
    func showKnot(_ shown: ShownKnot?, on mapView: MLNMapView) {
      guard let shown, shown.request != shownRequest else { return }
      shownRequest = shown.request
      following = false
      mapView.setCenter(
        CLLocationCoordinate2D(latitude: shown.knot.latitude, longitude: shown.knot.longitude),
        zoomLevel: navigationZoom, animated: true)
    }

    /// Back to the rider at the navigation zoom, following them again.
    @objc func recenter() {
      guard let mapView, let position else { return }
      following = true
      mapView.setCenter(
        CLLocationCoordinate2D(latitude: position.latitude, longitude: position.longitude),
        zoomLevel: navigationZoom, animated: true)
    }

    /// Moving or zooming the map by hand stops following the rider; the app's own camera moves
    /// don't.
    func mapView(_ mapView: MLNMapView, regionWillChangeWith reason: MLNCameraChangeReason, animated: Bool) {
      let gestures: MLNCameraChangeReason = [
        .gesturePan, .gesturePinch, .gestureRotate, .gestureZoomIn, .gestureZoomOut, .gestureOneFingerZoom,
        .gestureTilt,
      ]
      if !reason.intersection(gestures).isEmpty { following = false }
    }

    func showTrack(_ newTrack: RiddenTrack?) {
      guard newTrack !== track else { return }
      track = newTrack
      updateTrack()
    }

    private var navigating = false
    private var courseAhead: [GeoPoint]?

    private var geometryAhead: NetworkGeometry?

    func showLegAhead(
      navigating newNavigating: Bool, courseAhead newCourseAhead: [GeoPoint]?, geometry: NetworkGeometry?
    ) {
      guard newNavigating != navigating || newCourseAhead != courseAhead || geometry !== geometryAhead
      else { return }
      geometryAhead = geometry
      navigating = newNavigating
      courseAhead = newCourseAhead
      updateLegAhead()
    }

    /// While navigating, the leg ahead stands out and the rest of the route is calm.
    private func updateLegAhead() {
      guard let style else { return }
      (style.source(withIdentifier: "route-ahead") as? MLNShapeSource)?.shape =
        shape(MapFeatures.shared.legAhead(course: courseAhead, geometry: geometryAhead))
      for identifier in ["route", "route-bridge"] {
        (style.layer(withIdentifier: identifier) as? MLNLineStyleLayer)?.lineWidth =
          NSExpression(forConstantValue: navigating ? routeWidthCalm : routeWidth)
      }
      style.layer(withIdentifier: "route-direction")?.isVisible = !navigating
    }

    private func updateTrack() {
      guard let source = style?.source(withIdentifier: "ridden-track") as? MLNShapeSource else { return }
      var coordinates = (track?.points ?? []).map {
        CLLocationCoordinate2D(latitude: $0.latitude, longitude: $0.longitude)
      }
      source.shape = coordinates.count < 2 ? nil : MLNPolylineFeature(coordinates: &coordinates, count: UInt(coordinates.count))
    }

    /// Shows the rider and the next knot; when navigation begins or the app is opened while
    /// navigating, the map moves to the rider, see `knot-navigation` "Looking at the map".
    func showNavigation(
      position newPosition: Fix?, nextKnot newNextKnot: Knot?, wayToRoute newWayToRoute: GeoPoint?, guidedWay newGuidedWay: [GeoPoint]?, direction newDirection: Double?,
      on mapView: MLNMapView
    ) {
      guard newPosition !== position || newNextKnot !== nextKnot || newWayToRoute != wayToRoute || newGuidedWay != guidedWay else { return }
      let begins = newPosition != nil && (position == nil || findRider)
      if begins { findRider = false }
      position = newPosition
      nextKnot = newNextKnot
      wayToRoute = newWayToRoute
      guidedWay = newGuidedWay
      direction = newDirection
      if begins { following = true }
      if newPosition == nil { following = false }
      updateRecenterButton()
      updateNavigation()
      guard following, let newPosition else { return }
      if let newWayToRoute {
        // Off route, the rider and the end of the way back, so they see where the route is, no
        // closer than following, as the way back can be short.
        let rider = CLLocationCoordinate2D(latitude: newPosition.latitude, longitude: newPosition.longitude)
        let end = CLLocationCoordinate2D(latitude: newWayToRoute.latitude, longitude: newWayToRoute.longitude)
        let bounds = MLNCoordinateBounds(
          sw: CLLocationCoordinate2D(latitude: min(rider.latitude, end.latitude), longitude: min(rider.longitude, end.longitude)),
          ne: CLLocationCoordinate2D(latitude: max(rider.latitude, end.latitude), longitude: max(rider.longitude, end.longitude)))
        let padding = clearPadding(in: mapView)
        let camera = mapView.cameraThatFitsCoordinateBounds(bounds, edgePadding: padding)
        camera.altitude = max(
          camera.altitude,
          MLNAltitudeForZoomLevel(navigationZoom, camera.pitch, camera.centerCoordinate.latitude, mapView.frame.size))
        center(camera, on: bounds, padding: padding, in: mapView)
        mapView.setCamera(camera, animated: true)
      } else if begins {
        mapView.setCenter(
          CLLocationCoordinate2D(latitude: newPosition.latitude, longitude: newPosition.longitude),
          zoomLevel: max(mapView.zoomLevel, navigationZoom), animated: true)
      } else {
        mapView.setCenter(
          CLLocationCoordinate2D(latitude: newPosition.latitude, longitude: newPosition.longitude), animated: true)
      }
    }

    private func updateNavigation() {
      func point(_ latitude: Double, _ longitude: Double) -> MLNPointFeature {
        let point = MLNPointFeature()
        point.coordinate = CLLocationCoordinate2D(latitude: latitude, longitude: longitude)
        return point
      }
      // With a riding direction, the position is drawn as an arrow rotated by it, see
      // `knot-navigation` "Riding direction on the map".
      (style?.source(withIdentifier: "position") as? MLNShapeSource)?.shape =
        position.map {
          let feature = point($0.latitude, $0.longitude)
          if let direction { feature.attributes = ["direction": direction] }
          return feature
        }
      // At each of its signposts, see `map-planning` "Knots signposted at several places".
      (style?.source(withIdentifier: "next-knot") as? MLNShapeSource)?.shape =
        nextKnot.map { knot in
          MLNShapeCollection(shapes: knot.positions.map { point($0.latitude, $0.longitude) })
        }
      // Off route, the straight way back to the route, see `knot-navigation` "Way to the route on
      // the map".
      var way: MLNShape? = nil
      if let position, let wayToRoute, guidedWay == nil {
        var coordinates = [
          CLLocationCoordinate2D(latitude: position.latitude, longitude: position.longitude),
          CLLocationCoordinate2D(latitude: wayToRoute.latitude, longitude: wayToRoute.longitude),
        ]
        way = MLNPolylineFeature(coordinates: &coordinates, count: 2)
      }
      (style?.source(withIdentifier: "way-to-route") as? MLNShapeSource)?.shape = way
      var guided: MLNShape? = nil
      if let guidedWay, guidedWay.count >= 2 {
        var coordinates = guidedWay.map { CLLocationCoordinate2D(latitude: $0.latitude, longitude: $0.longitude) }
        guided = MLNPolylineFeature(coordinates: &coordinates, count: UInt(coordinates.count))
      }
      (style?.source(withIdentifier: "guided-way") as? MLNShapeSource)?.shape = guided
    }

    func showOffer(_ place: GeoPoint?) {
      guard place !== offerPlace else { return }
      offerPlace = place
      updateOffer()
    }

    private func updateOffer() {
      guard let source = style?.source(withIdentifier: "offer") as? MLNShapeSource else { return }
      if let offerPlace {
        let point = MLNPointFeature()
        point.coordinate = CLLocationCoordinate2D(latitude: offerPlace.latitude, longitude: offerPlace.longitude)
        source.shape = point
      } else {
        source.shape = nil
      }
    }

    /// Keeps the offered place's choices next to its flag while the map moves.
    private func reportOffer(on mapView: MLNMapView) {
      guard let offerPlace else { return }
      onOfferMoved(
        mapView.convert(
          CLLocationCoordinate2D(latitude: offerPlace.latitude, longitude: offerPlace.longitude), toPointTo: mapView))
    }

    func mapViewRegionIsChanging(_ mapView: MLNMapView) {
      reportOffer(on: mapView)
    }

    private func updateMarker() {
      guard let source = style?.source(withIdentifier: "marker") as? MLNShapeSource else { return }
      if let marker {
        let point = MLNPointFeature()
        point.coordinate = CLLocationCoordinate2D(latitude: marker.latitude, longitude: marker.longitude)
        source.shape = point
      } else {
        source.shape = nil
      }
    }

    func mapView(_ mapView: MLNMapView, regionDidChangeAnimated animated: Bool) {
      reportOffer(on: mapView)
      onMove(
        CameraPlace(
          latitude: mapView.centerCoordinate.latitude, longitude: mapView.centerCoordinate.longitude,
          zoom: mapView.zoomLevel),
        knotArea(of: mapView))
    }
    /// Whether the map already shows a place to keep, e.g. the one saved when the app was left.
    var hasPlace = false
    private var leaving: NSObjectProtocol?

    /// Saves the map's place whenever the app goes to the background.
    func observeLeaving(of mapView: MLNMapView) {
      leaving = NotificationCenter.default.addObserver(
        forName: UIApplication.didEnterBackgroundNotification, object: nil, queue: .main
      ) { [weak self, weak mapView] _ in
        guard let self, let mapView else { return }
        self.onLeave(
          CameraPlace(
            latitude: mapView.centerCoordinate.latitude, longitude: mapView.centerCoordinate.longitude,
            zoom: mapView.zoomLevel))
      }
      returning = NotificationCenter.default.addObserver(
        forName: UIApplication.willEnterForegroundNotification, object: nil, queue: .main
      ) { [weak self] _ in self?.findRider = true }
      // Appearance changes in the background are skipped, see `reloadStyleIfAppearanceChanged`.
      active = NotificationCenter.default.addObserver(
        forName: UIApplication.didBecomeActiveNotification, object: nil, queue: .main
      ) { [weak self, weak mapView] _ in
        if let self, let mapView { self.reloadStyleIfAppearanceChanged(on: mapView) }
      }
    }
    private var active: NSObjectProtocol?
    private var returning: NSObjectProtocol?
    private weak var mapView: MLNMapView?
    private(set) var style: MLNStyle?
    private var graph: NetworkGraph?
    private var layers: MapLayers?
    private var focus: [Knot] = []
    private var shownGraph: NetworkGraph?
    private var shownNetwork: URL?
    private var shownRoute: String?

    func show(graph: NetworkGraph?, layers: MapLayers?, focus: [Knot], on mapView: MLNMapView) {
      self.mapView = mapView
      self.graph = graph
      self.layers = layers
      self.focus = focus
      update()
    }

    @objc func zoomIn() { zoom(by: 1) }

    @objc func zoomOut() { zoom(by: -1) }

    private func zoom(by delta: Double) {
      guard let mapView else { return }
      mapView.setZoomLevel(mapView.zoomLevel + delta, animated: true)
    }

    @objc func tapped(_ recognizer: UITapGestureRecognizer) {
      guard let mapView else { return }
      let point = recognizer.location(in: mapView)
      if mapView.zoomLevel < knotMinimumZoom {
        // Zoomed out, knots are not shown: a tap on the route zooms to it.
        let area = CGRect(x: point.x - touchTargetPoints, y: point.y - touchTargetPoints, width: 2 * touchTargetPoints, height: 2 * touchTargetPoints)
        if !mapView.visibleFeatures(in: area, styleLayerIdentifiers: ["route"]).isEmpty { fit(to: focus, animated: true) }
        return
      }
      let coordinate = mapView.convert(point, toCoordinateFrom: mapView)
      let metersPerPoint = mapView.metersPerPoint(atLatitude: coordinate.latitude)
      onTap(coordinate.latitude, coordinate.longitude, metersPerPoint * touchTargetPoints, point)
    }

    private var coursesHandedOver = false

    /// Called after every rendered frame until the knots and the courses are visible: MapLibre
    /// parses large layers on its own, so they show up some time after they were handed over.
    func mapViewDidFinishRenderingFrame(_ mapView: MLNMapView, fullyRendered: Bool) {
      guard !StartupMarks.isMarked("courses") else { return }
      if !mapView.visibleFeatures(in: mapView.bounds, styleLayerIdentifiers: ["knots"]).isEmpty {
        StartupMarks.mark("knots")
      }
      if coursesHandedOver,
        !mapView.visibleFeatures(in: mapView.bounds, styleLayerIdentifiers: ["connections"]).isEmpty
      {
        StartupMarks.mark("courses")
      }
    }

    func mapView(_ mapView: MLNMapView, didFinishLoading style: MLNStyle) {
      StartupMarks.mark("map")
      self.style = style
      styleDark = loadingDark
      shownNetwork = nil
      shownRoute = nil
      addLayers(to: style)
      update()
      // The appearance may have changed again while this style was loading.
      reloadStyleIfAppearanceChanged(on: mapView)
    }

    func mapViewDidFailLoadingMap(_ mapView: MLNMapView, withError error: Error) {
      useOfflineStyle(on: mapView)
    }

    /// Whether the offline style is shown, so the base map is loaded once internet access is back.
    private(set) var usesOfflineStyle = false

    /// Whether the system is in dark mode; the next style loaded follows it.
    var dark = false

    /// Whether the device has internet access, to load the base map again after falling back.
    var online = false

    /// The appearance of the style being loaded and of the loaded one, to see whether it still
    /// matches `dark`.
    private var loadingDark = false
    private var styleDark: Bool?

    func loadBaseMap(on mapView: MLNMapView) {
      usesOfflineStyle = false
      load(baseMapStyle(dark: dark), on: mapView)
    }

    func useOfflineStyle(on mapView: MLNMapView, again: Bool = false) {
      guard !usesOfflineStyle || again else { return }
      usesOfflineStyle = true
      let file = FileManager.default.temporaryDirectory
        .appendingPathComponent("offline-style-\(dark ? "dark" : "light").json")
      try? Data(offlineStyle(dark: dark).utf8).write(to: file)
      load(file, on: mapView)
    }

    /// Loads the same kind of style, base map or offline, again when the appearance changed.
    /// Not in the background: iOS switches the appearance there back and forth to take the app
    /// switcher's snapshots in both, see `map-planning` "Returning to the app".
    func reloadStyleIfAppearanceChanged(on mapView: MLNMapView) {
      guard UIApplication.shared.applicationState != .background else { return }
      guard let styleDark, styleDark != dark else { return }
      if usesOfflineStyle { useOfflineStyle(on: mapView, again: true) } else { loadBaseMap(on: mapView) }
    }

    /// MapLibre invalidates a style as soon as the next one starts loading; until that one is
    /// loaded, updates wait for `didFinishLoading`, which adds everything again.
    private func load(_ url: URL, on mapView: MLNMapView) {
      loadingDark = dark
      style = nil
      styleDark = nil
      mapView.styleURL = url
    }

    private func update() {
      guard let style, let layers else { return }
      updateBridges(on: style)
      if shownNetwork != layers.connections {
        for ref in layers.refs where style.image(forName: KnotBadges.name(nil, ref)) == nil {
          style.setImage(KnotBadges.image(nil, ref), forName: KnotBadges.name(nil, ref))
        }
        (style.source(withIdentifier: "knots") as? MLNShapeSource)?.url = layers.knots
        (style.source(withIdentifier: "connections") as? MLNShapeSource)?.url = layers.connections
        shownNetwork = layers.connections
        coursesHandedOver = layers.hasCourses
      }
      if shownRoute != layers.route + layers.routeKnots + layers.routePointWays {
        // Route knots change without the route, e.g. when only the start is set.
        for routeKnot in layers.routeKnotList {
          let name = KnotBadges.name(routeKnot.role, routeKnot.knot.ref)
          if style.image(forName: name) == nil { style.setImage(KnotBadges.image(routeKnot.role, routeKnot.knot.ref), forName: name) }
        }
        (style.source(withIdentifier: "route") as? MLNShapeSource)?.shape = shape(layers.route)
        (style.source(withIdentifier: "route-knots") as? MLNShapeSource)?.shape = shape(layers.routeKnots)
        (style.source(withIdentifier: "route-point-ways") as? MLNShapeSource)?.shape = shape(layers.routePointWays)
        shownRoute = layers.route + layers.routeKnots + layers.routePointWays
      }
      if shownGraph !== graph, let graph {
        // The map keeps its place: the one saved when the app was left, or the one before
        // switching to another network. Without one, it shows the route if there is one, or the
        // network's center. Either way knots must be shown, see `map-planning`.
        if !hasPlace {
          fit(to: focus.count >= 2 ? focus : Array(graph.knots.values), animated: false)
        }
        hasPlace = true
        if let mapView, mapView.zoomLevel < knotMinimumZoom {
          mapView.setZoomLevel(knotMinimumZoom, animated: false)
        }
        shownGraph = graph
      }
    }

    /// The room around knots fitted into view. In portrait, clear of the network switch at the top
    /// and of the search and the sheet at the bottom; in landscape, the panel is beside the map and
    /// the search at its bottom, and the map is too low for the portrait room, which zoomed out to
    /// the whole region.
    private func edgePadding(in mapView: MLNMapView) -> UIEdgeInsets {
      mapView.bounds.width > mapView.bounds.height
        ? UIEdgeInsets(top: 72, left: 40, bottom: 96, right: 80)
        : UIEdgeInsets(top: 140, left: 40, bottom: 260, right: 60)
    }

    /// [edgePadding] with room for a badge and its ring at the edge of the area.
    private func clearPadding(in mapView: MLNMapView) -> UIEdgeInsets {
      let padding = edgePadding(in: mapView)
      return UIEdgeInsets(
        top: padding.top + 24, left: padding.left + 16, bottom: padding.bottom + 32, right: padding.right + 16)
    }

    /// Moves `camera` so the middle of `bounds` is in the middle of the area left by `padding`. A
    /// fitted camera has it in the middle of the whole map, which lies below the search field and
    /// the panel, so what is at the lower edge of `bounds` is hidden behind them.
    private func center(
      _ camera: MLNMapCamera, on bounds: MLNCoordinateBounds, padding: UIEdgeInsets, in mapView: MLNMapView
    ) {
      let latitude = (bounds.sw.latitude + bounds.ne.latitude) / 2
      let longitude = (bounds.sw.longitude + bounds.ne.longitude) / 2
      let zoom = MLNZoomLevelForAltitude(camera.altitude, camera.pitch, latitude, mapView.frame.size)
      let pointsPerDegree = 512 * pow(2, zoom) / 360
      camera.centerCoordinate = CLLocationCoordinate2D(
        latitude: latitude + (padding.top - padding.bottom) / 2 * cos(latitude * .pi / 180) / pointsPerDegree,
        longitude: longitude - (padding.left - padding.right) / 2 / pointsPerDegree)
    }

    private func fit(to knots: [Knot], animated: Bool) {
      guard knots.count >= 2, let mapView else { return }
      let coordinates = knots.map { CLLocationCoordinate2D(latitude: $0.latitude, longitude: $0.longitude) }
      let bounds = MLNCoordinateBounds(
        sw: CLLocationCoordinate2D(
          latitude: coordinates.map(\.latitude).min()!, longitude: coordinates.map(\.longitude).min()!),
        ne: CLLocationCoordinate2D(
          latitude: coordinates.map(\.latitude).max()!, longitude: coordinates.map(\.longitude).max()!))
      mapView.setVisibleCoordinateBounds(
        bounds, edgePadding: edgePadding(in: mapView), animated: animated,
        completionHandler: nil)
    }

    private func shape(_ geoJson: String) -> MLNShape? {
      try? MLNShape(data: Data(geoJson.utf8), encoding: String.Encoding.utf8.rawValue)
    }

    /// Adds the bridges over the route when the shown geometry has bridge stretches, and takes them
    /// away when it has none, see `map-planning` "Route and bridges" and "Bridge edges on the
    /// route": semi-transparent copies of the base map's bridge layers, then the stretches of the
    /// lines that run on a bridge on top of them, and the edges of a bridge along the route, all
    /// below the ridden track, which stays visible on a bridge. The offline style has no bridge
    /// layers, so nothing is copied there.
    private func updateBridges(on style: MLNStyle) {
      let wanted = layers?.geometry?.hasBridges == true
      let present = style.layer(withIdentifier: "connections-bridge") != nil
      guard wanted != present, let track = style.layer(withIdentifier: "ridden-track") else { return }
      guard wanted else {
        for layer in style.layers
        where layer.identifier.hasSuffix(bridgeCopySuffix) || layer.identifier.hasSuffix(bridgeEdgesSuffix)
          || bridgeLines.contains(where: { $0.1 == layer.identifier })
        {
          style.removeLayer(layer)
        }
        return
      }
      let bridges = style.layers.compactMap { $0 as? MLNLineStyleLayer }.filter { isBaseMapBridge($0.identifier) }
      guard !bridges.isEmpty else { return }
      for bridge in bridges {
        guard let copy = copyOf(bridge, identifier: bridge.identifier + bridgeCopySuffix, in: style) else { continue }
        copy.sourceLayerIdentifier = bridge.sourceLayerIdentifier
        copy.predicate = bridge.predicate
        copy.lineOpacity = NSExpression(forConstantValue: bridgeOpacity)
        style.insertLayer(copy, below: track)
      }
      let bridgePredicate = NSPredicate(format: "bridge == YES")
      func onBridge(_ layer: MLNLineStyleLayer) -> NSPredicate {
        layer.predicate.map { NSCompoundPredicate(andPredicateWithSubpredicates: [$0, bridgePredicate]) }
          ?? bridgePredicate
      }
      for (original, identifier) in bridgeLines {
        guard let line = style.layer(withIdentifier: original) as? MLNLineStyleLayer,
          let copy = copyOf(line, identifier: identifier, in: style)
        else { continue }
        copy.predicate = onBridge(line)
        style.insertLayer(copy, below: track)
      }
      for (original, width) in [("route", routeWidth), ("route-ahead", routeWidthAhead)] {
        guard let line = style.layer(withIdentifier: original) as? MLNLineStyleLayer,
          let sourceIdentifier = line.sourceIdentifier, let source = style.source(withIdentifier: sourceIdentifier)
        else { continue }
        let edges = MLNLineStyleLayer(identifier: original + bridgeEdgesSuffix, source: source)
        edges.predicate = onBridge(line)
        edges.lineColor = NSExpression(
          forConstantValue: styleDark == true
            ? UIColor(red: 0xCF / 255, green: 0xD8 / 255, blue: 0xDC / 255, alpha: 1)
            : UIColor(red: 0x37 / 255, green: 0x47 / 255, blue: 0x4F / 255, alpha: 1))
        edges.lineOpacity = NSExpression(forConstantValue: bridgeEdgeOpacity)
        edges.lineWidth = NSExpression(forConstantValue: bridgeEdgeWidth)
        edges.lineGapWidth = NSExpression(forConstantValue: width + 2)
        edges.lineOffset = NSExpression(forConstantValue: routeOffset)
        style.insertLayer(edges, below: track)
      }
    }

    /// A line layer drawn like `layer`, from the same source, with the identifier `identifier`.
    private func copyOf(_ layer: MLNLineStyleLayer, identifier: String, in style: MLNStyle) -> MLNLineStyleLayer? {
      guard let sourceIdentifier = layer.sourceIdentifier, let source = style.source(withIdentifier: sourceIdentifier)
      else { return nil }
      let copy = MLNLineStyleLayer(identifier: identifier, source: source)
      copy.minimumZoomLevel = layer.minimumZoomLevel
      copy.maximumZoomLevel = layer.maximumZoomLevel
      copy.lineColor = layer.lineColor
      copy.lineWidth = layer.lineWidth
      copy.lineGapWidth = layer.lineGapWidth
      copy.lineOffset = layer.lineOffset
      copy.lineOpacity = layer.lineOpacity
      copy.lineDashPattern = layer.lineDashPattern
      copy.lineCap = layer.lineCap
      copy.lineJoin = layer.lineJoin
      return copy
    }

    private func addLayers(to style: MLNStyle) {
      // Large network layers come from files, so the map parses them off the main thread.
      let sources = ["connections", "route", "route-knots", "knots"].map { MLNShapeSource(identifier: $0, shape: nil) }
      // Not "arrow": the base map's sprite has an image of that name for one-way streets.
      style.setImage(KnotBadges.arrow(), forName: "route-arrow")
      sources.forEach(style.addSource)

      // The chosen search hit, drawn under connections, route and knots, so it never hides a knot.
      let markerSource = MLNShapeSource(identifier: "marker", shape: nil)
      style.addSource(markerSource)
      let markerLayer = MLNCircleStyleLayer(identifier: "marker", source: markerSource)
      markerLayer.circleRadius = NSExpression(forConstantValue: 12)
      markerLayer.circleColor = NSExpression(forConstantValue: UIColor(red: 0.85, green: 0.19, blue: 0.15, alpha: 1))
      markerLayer.circleStrokeColor = NSExpression(forConstantValue: UIColor.white)
      markerLayer.circleStrokeWidth = NSExpression(forConstantValue: 3)
      style.addLayer(markerLayer)
      updateMarker()

      let connections = MLNLineStyleLayer(identifier: "connections", source: sources[0])
      connections.lineColor = NSExpression(forConstantValue: UIColor(Color.knoopGreen))
      connections.lineWidth = NSExpression(forConstantValue: 2)
      connections.lineOpacity = NSExpression(forConstantValue: 0.7)
      style.addLayer(connections)

      let route = MLNLineStyleLayer(identifier: "route", source: sources[1])
      route.predicate = NSPredicate(format: "reachable == YES")
      route.lineColor = NSExpression(forConstantValue: UIColor(Color.knoopOrange))
      route.lineWidth = NSExpression(forConstantValue: routeWidth)
      // To the right of the riding direction, so a stretch used both ways shows as two lines, see
      // `map-planning` "Route used in both directions".
      route.lineOffset = NSExpression(forConstantValue: routeOffset)
      route.lineCap = NSExpression(forConstantValue: "round")
      route.lineJoin = NSExpression(forConstantValue: "round")
      style.addLayer(route)

      let unreachable = MLNLineStyleLayer(identifier: "route-unreachable", source: sources[1])
      unreachable.predicate = NSPredicate(format: "reachable == NO")
      unreachable.lineColor = NSExpression(forConstantValue: UIColor.systemRed)
      unreachable.lineWidth = NSExpression(forConstantValue: 4)
      unreachable.lineDashPattern = NSExpression(forConstantValue: [2, 2])
      style.addLayer(unreachable)

      // Arrows along the route show the riding direction: each leg runs from its start to its end.
      let direction = MLNSymbolStyleLayer(identifier: "route-direction", source: sources[1])
      direction.predicate = NSPredicate(format: "reachable == YES")
      direction.symbolPlacement = NSExpression(forConstantValue: "line")
      direction.symbolSpacing = NSExpression(forConstantValue: 48)
      direction.iconImageName = NSExpression(forConstantValue: "route-arrow")
      direction.iconOffset = NSExpression(forConstantValue: NSValue(cgVector: CGVector(dx: 0, dy: routeOffset)))
      direction.iconAllowsOverlap = NSExpression(forConstantValue: true)
      direction.iconIgnoresPlacement = NSExpression(forConstantValue: true)
      style.addLayer(direction)

      // The ways of route points over the route: dots along paths, long dashes where only a
      // straight line is known, see `map-planning` "The line on the map".
      let pointWaysSource = MLNShapeSource(identifier: "route-point-ways", shape: nil)
      style.addSource(pointWaysSource)
      let pointWays = MLNLineStyleLayer(identifier: "route-point-ways", source: pointWaysSource)
      pointWays.predicate = NSPredicate(format: "straight == NO")
      pointWays.lineColor = NSExpression(forConstantValue: UIColor.white)
      pointWays.lineWidth = NSExpression(forConstantValue: 2)
      pointWays.lineDashPattern = NSExpression(forConstantValue: [0.1, 2])
      pointWays.lineCap = NSExpression(forConstantValue: "round")
      style.addLayer(pointWays)
      let pointStraight = MLNLineStyleLayer(identifier: "route-point-straight", source: pointWaysSource)
      pointStraight.predicate = NSPredicate(format: "straight == YES")
      pointStraight.lineColor = NSExpression(forConstantValue: UIColor.white)
      pointStraight.lineWidth = NSExpression(forConstantValue: 2)
      pointStraight.lineDashPattern = NSExpression(forConstantValue: [3, 3])
      style.addLayer(pointStraight)

      // While navigating, the course to the next knot, see `knot-navigation` "Leg ahead on the map".
      let aheadSource = MLNShapeSource(identifier: "route-ahead", shape: nil)
      style.addSource(aheadSource)
      let ahead = MLNLineStyleLayer(identifier: "route-ahead", source: aheadSource)
      ahead.lineColor = NSExpression(forConstantValue: UIColor(Color.knoopOrange))
      ahead.lineWidth = NSExpression(forConstantValue: routeWidthAhead)
      ahead.lineOffset = NSExpression(forConstantValue: routeOffset)
      ahead.lineCap = NSExpression(forConstantValue: "round")
      ahead.lineJoin = NSExpression(forConstantValue: "round")
      style.addLayer(ahead)
      let aheadDirection = MLNSymbolStyleLayer(identifier: "route-ahead-direction", source: aheadSource)
      aheadDirection.symbolPlacement = NSExpression(forConstantValue: "line")
      aheadDirection.symbolSpacing = NSExpression(forConstantValue: 48)
      aheadDirection.iconImageName = NSExpression(forConstantValue: "route-arrow")
      aheadDirection.iconOffset = NSExpression(forConstantValue: NSValue(cgVector: CGVector(dx: 0, dy: routeOffset)))
      aheadDirection.iconAllowsOverlap = NSExpression(forConstantValue: true)
      aheadDirection.iconIgnoresPlacement = NSExpression(forConstantValue: true)
      style.addLayer(aheadDirection)

      // On top of the route and its arrows, half as wide: the ridden part shows blue with the route's
      // orange at its edges, see `knot-navigation` "Ridden track".
      let trackSource = MLNShapeSource(identifier: "ridden-track", shape: nil)
      style.addSource(trackSource)
      let trackLayer = MLNLineStyleLayer(identifier: "ridden-track", source: trackSource)
      trackLayer.lineColor = NSExpression(forConstantValue: UIColor(red: 0x1E / 255, green: 0x6F / 255, blue: 0xD9 / 255, alpha: 1))
      trackLayer.lineWidth = NSExpression(forConstantValue: trackWidth)
      trackLayer.lineOffset = NSExpression(forConstantValue: routeOffset)
      trackLayer.lineCap = NSExpression(forConstantValue: "round")
      trackLayer.lineJoin = NSExpression(forConstantValue: "round")
      style.addLayer(trackLayer)
      updateTrack()
      updateLegAhead()

      let knots = MLNSymbolStyleLayer(identifier: "knots", source: sources[3])
      knots.iconImageName = NSExpression(format: "mgl_join({'knot-', ref})")
      knots.iconAllowsOverlap = NSExpression(forConstantValue: true)
      knots.iconIgnoresPlacement = NSExpression(forConstantValue: true)
      knots.minimumZoomLevel = Float(knotMinimumZoom)
      style.addLayer(knots)

      // The next knot while navigating: a ring under its badge.
      let waySource = MLNShapeSource(identifier: "way-to-route", shape: nil)
      style.addSource(waySource)
      let wayLayer = MLNLineStyleLayer(identifier: "way-to-route", source: waySource)
      wayLayer.lineColor = NSExpression(forConstantValue: UIColor.systemRed)
      wayLayer.lineWidth = NSExpression(forConstantValue: 4)
      wayLayer.lineDashPattern = NSExpression(forConstantValue: [2, 2])
      wayLayer.lineCap = NSExpression(forConstantValue: "round")
      style.addLayer(wayLayer)
      let guidedSource = MLNShapeSource(identifier: "guided-way", shape: nil)
      style.addSource(guidedSource)
      let guidedLayer = MLNLineStyleLayer(identifier: "guided-way", source: guidedSource)
      guidedLayer.lineColor = NSExpression(forConstantValue: UIColor.systemRed)
      guidedLayer.lineWidth = NSExpression(forConstantValue: 5)
      guidedLayer.lineCap = NSExpression(forConstantValue: "round")
      guidedLayer.lineJoin = NSExpression(forConstantValue: "round")
      style.addLayer(guidedLayer)
      let nextKnotSource = MLNShapeSource(identifier: "next-knot", shape: nil)
      style.addSource(nextKnotSource)
      let nextKnotLayer = MLNCircleStyleLayer(identifier: "next-knot", source: nextKnotSource)
      nextKnotLayer.circleRadius = NSExpression(forConstantValue: 22)
      nextKnotLayer.circleColor = NSExpression(forConstantValue: UIColor(Color.knoopOrange).withAlphaComponent(0.35))
      nextKnotLayer.circleStrokeColor = NSExpression(forConstantValue: UIColor(Color.knoopOrange))
      nextKnotLayer.circleStrokeWidth = NSExpression(forConstantValue: 3)
      style.addLayer(nextKnotLayer)

      // Route knots are drawn above the network's knots, with a badge per role.
      let routeKnots = MLNSymbolStyleLayer(identifier: "route-knots", source: sources[2])
      routeKnots.iconImageName = NSExpression(format: "mgl_join({'route-', role, '-', ref})")
      routeKnots.iconAllowsOverlap = NSExpression(forConstantValue: true)
      routeKnots.iconIgnoresPlacement = NSExpression(forConstantValue: true)
      routeKnots.minimumZoomLevel = Float(knotMinimumZoom)
      style.addLayer(routeKnots)

      // The tapped place while its choices are shown: a flag in a white badge, above the route, so
      // it is clear where a route point would go, see `map-planning` "Choose a route point on the map".
      style.setImage(KnotBadges.image(nil, ""), forName: "offer-flag")
      let offerSource = MLNShapeSource(identifier: "offer", shape: nil)
      style.addSource(offerSource)
      let offerLayer = MLNSymbolStyleLayer(identifier: "offer", source: offerSource)
      offerLayer.iconImageName = NSExpression(forConstantValue: "offer-flag")
      offerLayer.iconScale = NSExpression(forConstantValue: 1.4)
      offerLayer.iconAllowsOverlap = NSExpression(forConstantValue: true)
      offerLayer.iconIgnoresPlacement = NSExpression(forConstantValue: true)
      style.addLayer(offerLayer)
      updateOffer()

      // The rider's position while navigating, above everything else, in the blue maps use for it.
      // The position found on request while planning: a dot that does not follow the rider.
      let myPositionSource = MLNShapeSource(identifier: "my-position", shape: nil)
      style.addSource(myPositionSource)
      let myPositionLayer = MLNCircleStyleLayer(identifier: "my-position", source: myPositionSource)
      myPositionLayer.circleRadius = NSExpression(forConstantValue: 7)
      myPositionLayer.circleColor = NSExpression(forConstantValue: UIColor(red: 0x1A / 255, green: 0x73 / 255, blue: 0xE8 / 255, alpha: 1))
      myPositionLayer.circleStrokeColor = NSExpression(forConstantValue: UIColor.white)
      myPositionLayer.circleStrokeWidth = NSExpression(forConstantValue: 3)
      style.addLayer(myPositionLayer)
      let positionSource = MLNShapeSource(identifier: "position", shape: nil)
      style.addSource(positionSource)
      let positionLayer = MLNCircleStyleLayer(identifier: "position", source: positionSource)
      positionLayer.predicate = NSPredicate(format: "direction == nil")
      // 30 pt across with the outline, see `knot-navigation` "Riding direction on the map".
      positionLayer.circleRadius = NSExpression(forConstantValue: 12)
      positionLayer.circleColor = NSExpression(forConstantValue: UIColor.systemBlue)
      positionLayer.circleStrokeColor = NSExpression(forConstantValue: UIColor.white)
      positionLayer.circleStrokeWidth = NSExpression(forConstantValue: 3)
      style.addLayer(positionLayer)
      style.setImage(KnotBadges.riderArrow(), forName: "rider-arrow")
      let arrowLayer = MLNSymbolStyleLayer(identifier: "position-arrow", source: positionSource)
      arrowLayer.predicate = NSPredicate(format: "direction != nil")
      arrowLayer.iconImageName = NSExpression(forConstantValue: "rider-arrow")
      arrowLayer.iconRotation = NSExpression(forKeyPath: "direction")
      arrowLayer.iconRotationAlignment = NSExpression(forConstantValue: "map")
      arrowLayer.iconAllowsOverlap = NSExpression(forConstantValue: true)
      arrowLayer.iconIgnoresPlacement = NSExpression(forConstantValue: true)
      style.addLayer(arrowLayer)
      updateNavigation()
      updateMyPosition()
    }

  }
}
